package com.opensocket.aievent.core.a2a;
import java.util.*; import java.util.concurrent.CopyOnWriteArrayList; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.context.annotation.Profile; import org.springframework.stereotype.Repository;
@Repository @Profile("!prod") @ConditionalOnProperty(prefix="task",name="store",havingValue="MEMORY",matchIfMissing=true) public class InMemoryA2AAggregationEvidenceRepository implements A2AAggregationEvidenceRepository {private final List<A2AAggregationEvidence> values=new CopyOnWriteArrayList<>();public A2AAggregationEvidence save(A2AAggregationEvidence v){if(values.stream().noneMatch(x->Objects.equals(x.getTenantId(),v.getTenantId())&&Objects.equals(x.getParentTaskId(),v.getParentTaskId())&&Objects.equals(x.getComputationHash(),v.getComputationHash())&&Objects.equals(x.getEvidenceType(),v.getEvidenceType())))values.add(v);return v;}public List<A2AAggregationEvidence> findByParentTask(String t,String id,int n){return values.stream().filter(v->Objects.equals(t,v.getTenantId())&&Objects.equals(id,v.getParentTaskId())).sorted(Comparator.comparing(A2AAggregationEvidence::getOccurredAt).reversed()).limit(n).toList();}public String mode(){return "MEMORY";}}
